ed:{zh:"测试失败",en:"Test failed"},clear_all_cache_now:{zh:"立即清除全部缓存",en:"Clear all cache now"},clear_cache:{zh:"清除缓存",en:"Clear Cache"},disable_on_mobile:{zh:"移动端禁用",en:"Disable on Mobile"},clear_success:{zh:"清除成功",en:"Clear success"},clear_failed:{zh:"清除失败",en:"Clear failed"},share:{zh:"分享",en:"Share"},clear_all:{zh:"清空",en:"Clear All"},help:{zh:"求助",en:"Help"},restore_default:{zh:"恢复默认",en:"Restore Default"},shortcuts_setting:{zh:"快捷键设置",en:"Shortcuts Setting"},toggle_translate_shortcut:{zh:'"切换网页翻译"快捷键',en:'"Toggle Translate" Shortcut'},toggle_transonly_shortcut:{zh:'"切换仅显示译文"快捷键',en:'"Hide Original" Shortcut'},toggle_style_shortcut:{zh:'"切换样式"快捷键',en:'"Toggle Style" Shortcut'},toggle_popup_shortcut:{zh:'"打开弹窗"快捷键',en:'"Open Popup" Shortcut'},open_setting_shortcut:{zh:'"打开设置"快捷键',en:'"Open Setting" Shortcut'},firefox_shortcut_edit_hint:{zh:"Firefox 不支持直接打开扩展快捷键管理页。请在地址栏输入 about:addons，然后点击齿轮菜单中的“管理扩展快捷键”。",en:"Firefox cannot open the extension shortcut manager directly. Enter about:addons in the address bar, then select Manage Extension Shortcuts from the gear menu."},hide_fab_button:{zh:"隐藏悬浮按钮",en:"Hide Fab Button"},fab_always_show:{zh:"始终显示悬浮按钮",en:"Always show floating button"},fab_turn_off:{zh:"关闭悬浮按钮",en:"Turn off floating button"},fab_hidden_shortcut_hint:{zh:"悬浮按钮已关闭。可以使用 Alt+B 临时呼出悬浮按钮。",en:"The floating button is turned off. Press Alt+B to temporarily show it."},fab_exception_list:{zh:"悬浮按钮特例名单",en:"Fab Button Exception List"},fab_exception_list_helper:{zh:"全局显示时，命中名单的页面隐藏按钮；全局隐藏时，命中名单的页面显示按钮。支持星号(*)通配符，多个网址用换行或逗号分隔。",en:"When shown globally, matching pages hide the button; when hidden globally, matching pages show it. Supports * wildcards; separate URLs with newlines or commas."},fab_click_action:{zh:"单击悬浮按钮动作",en:"Single Click Fab Action"},fab_click_menu:{zh:"弹出菜单",en:"Popup Menu"},fab_click_translate:{zh:"直接翻译",en:"Translate"},fab_click_popup:{zh:"打开翻译面板",en:"Open Translation Panel"},hide_tran_button:{zh:"隐藏翻译按钮",en:"Hide Translate Button"},hide_click_